import Link from "next/link";
import { AppearanceControl } from "@/components/appearance-control";
import { requireAdminPage } from "@/lib/admin/page-auth";
import { reauthenticateAdmin } from "@/lib/admin/actions";
import { Button } from "@/components/ui/button";
export const dynamic = "force-dynamic";
export const revalidate = 0;
export const metadata = {
  title: "Operator · Mailloop",
  robots: { index: false, follow: false },
};
export default async function AdminLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  await requireAdminPage();
  return (
    <div className="page-container py-8">
      <header className="mb-8 space-y-4">
        <div className="policy-header flex items-center justify-between gap-4">
          <Link href="/admin" className="text-2xl font-semibold">
            Mailloop operator
          </Link>
          <AppearanceControl />
        </div>
        <nav aria-label="Operator navigation" className="flex flex-wrap gap-6">
          <Link href="/admin/users">Users</Link>
          <Link href="/admin/audit">Audit history</Link>
          <Link href="/admin/controls">Sending controls</Link>
          <Link href="/compose">Workspace</Link>
        </nav>
        <div className="flex flex-wrap items-center gap-4">
          <form action={reauthenticateAdmin}>
            <Button variant="outline">Verify Google identity</Button>
          </form>
          <p className="text-sm text-body">
            Changes require Google authentication within the past 15 minutes.
          </p>
        </div>
      </header>
      <main id="main-content" className="space-y-6">
        {children}
      </main>
    </div>
  );
}
